/// Look up Canonical Combining Class for a code point. Returns 0 if not found.
#[must_use]
pub fn ccc(cp: u32) -> u8 {
    match CCC_TABLE.binary_search_by_key(&cp, |&(c, _)| c) {
        Ok(i) => CCC_TABLE[i].1,
        Err(_) => 0,
    }
}

/// Look up canonical decomposition for a code point.
/// Returns None if the character has no canonical decomposition.
#[must_use]
pub fn canonical_decomposition(cp: u32) -> Option<&'static [u32]> {
    match CANONICAL_DECOMP_INDEX.binary_search_by_key(&cp, |&(c, _, _)| c) {
        Ok(i) => {
            let (_, off, len) = CANONICAL_DECOMP_INDEX[i];
            Some(&CANONICAL_DECOMP_DATA[off as usize..(off as usize + len as usize)])
        }
        Err(_) => None,
    }
}

/// Look up compatibility decomposition for a code point.
/// Returns the canonical decomposition if one exists, otherwise the
/// compatibility-only decomposition. Returns None if no decomposition.
#[must_use]
pub fn compatibility_decomposition(cp: u32) -> Option<&'static [u32]> {
    // Check canonical first
    if let Some(d) = canonical_decomposition(cp) {
        return Some(d);
    }
    // Check compatibility-only
    match COMPAT_DECOMP_INDEX.binary_search_by_key(&cp, |&(c, _, _)| c) {
        Ok(i) => {
            let (_, off, len) = COMPAT_DECOMP_INDEX[i];
            Some(&COMPAT_DECOMP_DATA[off as usize..(off as usize + len as usize)])
        }
        Err(_) => None,
    }
}

/// Look up canonical composition: (first, second) -> composed.
/// Returns None if no composition exists for this pair.
#[must_use]
pub fn canonical_composition(first: u32, second: u32) -> Option<u32> {
    match COMPOSITION_TABLE.binary_search_by_key(&(first, second), |&(a, b, _)| (a, b)) {
        Ok(i) => Some(COMPOSITION_TABLE[i].2),
        Err(_) => None,
    }
}
